        OutlinedButton.icon(onPressed:()async{await LocationService.ensurePermission();await onRefresh();},icon:const Icon(Icons.my_location),label:const Text('Autorizza e aggiorna posizione')),
      ],
      if(data?.hasPosition==true)...[
        Padding(padding:const EdgeInsets.symmetric(vertical:8),child:Text('${data!.solar?.label??'Fase solare non disponibile'} · ${habitatLabel(data.habitat)}\nAggiornato ${SolarContext.clock(data.generatedAt)} · ${data.weatherAvailable?'meteo disponibile':'meteo non disponibile'}',style:const TextStyle(fontSize:11,height:1.4,color:WildColors.muted))),
        Text(data.solar?.dark==true?'Avvistamento visivo al buio: condizioni limitate':'Specie da osservare adesso',style:const TextStyle(fontWeight:FontWeight.w800)),
        if(data.species.isEmpty)const Padding(padding:EdgeInsets.symmetric(vertical:10),child:Text('Nessuna specie con condizioni sufficienti dai dati disponibili. Non significa assenza di fauna.')),
        if(data.species.isNotEmpty)_strip(context,data.species.take(4).toList(),false),
