  void _sources(BuildContext context){final s=snapshot;showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(_)=>SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisSize:MainAxisSize.min,children:[const Text('Dati del Radar',style:WildText.display),Text('Posizione: ${s?.hasPosition==true?'recente, accuratezza ≤200 m':'non disponibile o insufficiente'}'),Text('Meteo Open-Meteo: ${s?.weatherAvailable==true?'aggiornato ${SolarContext.clock(s?.weatherAt)}':'non disponibile'}'),Text('Habitat © OpenStreetMap contributors · ODbL: ${habitatLabel(s?.habitat??'unknown')}. Contesto entro 1,4 km, non habitat esatto del punto.'),Text('Quota: ${s?.elevation?.round().toString()??'non affidabile'}${s?.elevation==null?'':' m'}'),const SizedBox(height:10),const Text('Il calcolo combina fase solare, stagionalità, habitat, quota disponibile, meteo e segnalazioni. Le regole editoriali non sono un modello statistico validato.'),const SizedBox(height:10),Text('Evidenze regionali: ${s?.evidenceAvailable==true?'dati disponibili':'nessuna evidenza recente disponibile'}. Archivio personale entro 25 km/365 giorni; campione GBIF entro 40 km/730 giorni; Community pubblica non verificata. Assenza di record non equivale ad assenza della specie.'),const SizedBox(height:10),const Text('I controlli sul campo confrontano visite entro 2 km, stessa fase solare e ultimi 90 giorni. Sono conteggi descrittivi, non una probabilità. Le passeggiate senza avvistamenti non sono controlli negativi automatici.'),const SizedBox(height:10),const Text('Le fototrappole non sono collegate: occorre una sorgente autorizzata. Non vengono simulate. Il Radar non pubblica la tua posizione; coordinate inviate ai servizi meteo, cartografici e GBIF per leggere il contesto.'),const SizedBox(height:10),const Text('Alba e tramonto sono approssimazioni astronomiche: rilievi, nuvole e ostacoli cambiano la luce effettiva.')]))));}
